    new_glyph->yOffset = yOffset;
    new_glyph->graphicType = graphicType;
    data.copy(c, data_length);
    return_trace (new_glyph);
}
```

`data.copy(c, data_length)` calls `UnsizedArrayOf::copy`:

```cpp
UnsizedArrayOf* copy (hb_serialize_context_t *c, unsigned count) const
{
    TRACE_SERIALIZE (this);
    auto *out = c->start_embed (this);
    if (unlikely (!as_array (count).copy (c))) return_trace (nullptr);
    return_trace (out);
}
```

`as_array(count)` returns `hb_array(arrayZ, count)` where `arrayZ` is `&data.arrayZ[0]`, which is `this + 8` (after the xOffset, yOffset, graphicType fields).

